using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends Firebase Authentication SMS to the phone number of the user. Works only when the current authorization state is authorizationStateWaitCode and the server returned code of the type authenticationCodeTypeFirebaseAndroid or authenticationCodeTypeFirebaseIos
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendAuthenticationFirebaseSmsAsync(string token = default)
    {

           using var activity =  StartCallActivity("SendAuthenticationFirebaseSmsAsync", typeof(SendAuthenticationFirebaseSms).FullName ?? "SendAuthenticationFirebaseSmsAsync");

           try
           {
             return client.SendAuthenticationFirebaseSmsAsync(token);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
